function groupBy(list, key) {
  const out = {};
  for (const item of list) (out[item[key]] ??= []).push(item);
  return out;
}

function chunk(arr, size) {
  const out = [];
  for (let i = 0; i < arr.length; i += size) out.push(arr.slice(i, i + size));
  return out;
}

function camelCase(s) {
  return s.replace(/-(\w)/g, (_, c) => c.toUpperCase());
}

function truncate(s, n) {
  return s.length > n ? s.slice(0, n) + "…" : s;
}

function wordFreq(text) {
  const out = {};
  for (const w of text.toLowerCase().split(/\s+/).filter(Boolean)) out[w] = (out[w] ?? 0) + 1;
  return out;
}

function pluck(list, key) {
  return list.map((x) => x[key]);
}

function cartTotal(cart) {
  return cart.reduce((sum, item) => sum + item.price * item.qty, 0);
}

function range(start, end, step = 1) {
  const out = [];
  for (let i = start; i < end; i += step) out.push(i);
  return out;
}

function zip(a, b) {
  return a.slice(0, b.length).map((x, i) => [x, b[i]]);
}

function mostFrequent(arr) {
  const count = new Map();
  for (const x of arr) count.set(x, (count.get(x) ?? 0) + 1);
  let best = arr[0];
  for (const [x, n] of count) if (n > count.get(best)) best = x;
  return best;
}

function romanToInt(s) {
  const v = { I: 1, V: 5, X: 10, L: 50, C: 100, D: 500, M: 1000 };
  let total = 0;
  for (let i = 0; i < s.length; i++) {
    const cur = v[s[i]];
    total += cur < (v[s[i + 1]] ?? 0) ? -cur : cur;
  }
  return total;
}

function ranking(students) {
  return [...students]
    .sort((a, b) => b.score - a.score || a.name.localeCompare(b.name))
    .map((s) => s.name);
}

function isBalanced(s) {
  const pairs = { ")": "(", "]": "[", "}": "{" };
  const stack = [];
  for (const c of s) {
    if ("([{".includes(c)) stack.push(c);
    else if (c in pairs && stack.pop() !== pairs[c]) return false;
  }
  return stack.length === 0;
}

function deepEqual(a, b) {
  if (a === b) return true;
  if (typeof a !== "object" || typeof b !== "object" || !a || !b) return false;
  const ka = Object.keys(a), kb = Object.keys(b);
  return ka.length === kb.length && ka.every((k) => deepEqual(a[k], b[k]));
}
